package vn.tuan.service;
import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import vn.tuan.entity.*;import vn.tuan.repository.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor
public class OrderLifecycleService {
 private final OrderRepository orders;private final ProductRepository products;private final ActorService actors;private final OrderEvents events;private final jakarta.persistence.EntityManager em;
 private Order locked(Integer id){Order o=orders.lockById(id).orElseThrow(()->new IllegalArgumentException("Không tìm thấy đơn"));em.refresh(o);return o;}
 private void restore(Order o){Map<Integer,Integer> totals=new java.util.TreeMap<>();for(OrderDetail d:o.getOrderDetails())totals.merge(d.getProduct().getId(),d.getQuantity(),Integer::sum);for(var e:totals.entrySet()){Product p=products.lockById(e.getKey()).orElseThrow();em.refresh(p);p.setStock(p.getStock()+e.getValue());p.setSoldCount(Math.max(0,p.getSoldCount()-e.getValue()));}}
 @Transactional public void vendor(String email,Integer id,String next){Order o=locked(id);actors.shop(email,o.getShop().getId());OrderRules.vendorTransition(o.getStatus(),next);if("CONFIRMED".equals(next))OrderRules.require("COD".equals(o.getPaymentMethod()) || "PAID".equals(o.getPaymentStatus()),"Chờ thanh toán trực tuyến thành công");if("CANCELLED".equals(next)){restore(o);if("PAID".equals(o.getPaymentStatus()))o.setPaymentStatus("REFUND_PENDING");}if("REFUNDED".equals(next)){o.setPaymentStatus("REFUNDED");o.setRefundedAt(LocalDateTime.now());}o.setStatus(next);events.changed(o);}
 @Transactional public void cancel(String email,Integer id){Order o=locked(id);Account a=actors.account(email);OrderRules.require(o.getAccount()!=null && o.getAccount().getId().equals(a.getId()),"Đơn không thuộc tài khoản");OrderRules.require("NEW".equals(o.getStatus()),"Chỉ hủy đơn mới");restore(o);if("PAID".equals(o.getPaymentStatus()))o.setPaymentStatus("REFUND_PENDING");o.setStatus("CANCELLED");events.changed(o);}
 @Transactional public void delivery(String email,Integer id,String next){Account a=actors.account(email);OrderRules.require("SHIPPER".equals(actors.role(a)),"Chỉ Shipper nhận giao");Order o=locked(id);
  if("SHIPPING".equals(next)){OrderRules.require("READY".equals(o.getStatus()) && o.getShipper()==null,"Đơn chưa sẵn sàng hoặc đã có người nhận");o.setShipper(a);}
  else if("COMPLETED".equals(next)){OrderRules.require("SHIPPING".equals(o.getStatus()) && o.getShipper()!=null && o.getShipper().getId().equals(a.getId()),"Bạn không được hoàn tất đơn này");o.setPaymentStatus("PAID");o.setCompletedAt(LocalDateTime.now());}
  else throw new IllegalArgumentException("Trạng thái giao hàng không hợp lệ");o.setStatus(next);events.changed(o);
 }
 @Transactional public void requestReturn(String email,Integer id,String reason){Account a=actors.account(email);Order o=locked(id);OrderRules.require(o.getAccount()!=null && o.getAccount().getId().equals(a.getId()),"Đơn không thuộc tài khoản");OrderRules.require("COMPLETED".equals(o.getStatus()) && o.getCompletedAt()!=null && o.getCompletedAt().isAfter(LocalDateTime.now().minusDays(7)),"Chỉ yêu cầu trả hàng trong 7 ngày sau giao");OrderRules.require(reason!=null && reason.trim().length()>=10 && reason.length()<=500,"Lý do từ 10 đến 500 ký tự");o.setReturnReason(reason.trim());o.setStatus("RETURN_REQUESTED");events.changed(o);}
 @Transactional public void expire(Integer id){Order o=locked(id);if("VNPAY".equals(o.getPaymentMethod()) && java.util.Set.of("UNPAID","FAILED").contains(o.getPaymentStatus()) && "NEW".equals(o.getStatus()) && o.getPaymentExpiresAt()!=null && o.getPaymentExpiresAt().isBefore(LocalDateTime.now())){restore(o);o.setStatus("CANCELLED");events.changed(o);}}
 @Transactional public void confirmRefund(String email,Integer id){Order o=locked(id);actors.shop(email,o.getShop().getId());OrderRules.require("CANCELLED".equals(o.getStatus()) && "REFUND_PENDING".equals(o.getPaymentStatus()),"Đơn không chờ hoàn tiền");o.setPaymentStatus("REFUNDED");o.setRefundedAt(LocalDateTime.now());events.changed(o);}
}
